import bpy, json, os
root=r'C:\Users\myw\Documents\ChatGPT\硬件\modeling'
with open(os.path.join(root,'references','source_meshes.json'),'r',encoding='utf-8') as f: src=json.load(f)
scene=bpy.context.scene
ref=bpy.data.collections.get('99_SourceReferences')
if ref is None: ref=bpy.data.collections.new('99_SourceReferences'); scene.collection.children.link(ref)
for ob in list(bpy.data.objects):
    if ob.name.startswith('SRC_'): bpy.data.objects.remove(ob,do_unlink=True)
for me in list(bpy.data.meshes):
    if me.users==0: bpy.data.meshes.remove(me)
def material(name,color,rough=0.42,metallic=0.0):
    m=bpy.data.materials.get(name) or bpy.data.materials.new(name); m.diffuse_color=(*color,1); m.use_nodes=True
    bs=m.node_tree.nodes.get('Principled BSDF')
    if bs is None: bs=m.node_tree.nodes.new('ShaderNodeBsdfPrincipled')
    bs.inputs['Base Color'].default_value=(*color,1); bs.inputs['Roughness'].default_value=rough; bs.inputs['Metallic'].default_value=metallic
    return m
case_mat=material('Source CAD | neutral polymer',(0.68,0.72,0.75),.48); control_mat=material('Source CAD | neutral resin',(0.82,0.84,0.86),.3)
def build_mesh(record,name,transform,mat,smooth):
    verts=[transform(tuple(v)) for v in record['vertex_data']]; faces=[tuple(t) for t in record['triangle_data']]
    me=bpy.data.meshes.new(name+'_Mesh'); me.from_pydata(verts,[],faces); me.update()
    ob=bpy.data.objects.new(name,me); ref.objects.link(ob); ob.data.materials.append(mat)
    for p in me.polygons: p.use_smooth=smooth
    ob['source_file']=record.get('source',''); ob['source_entry']=record.get('entry',''); ob['source_units']='millimeter'; ob['source_bounds_mm']=json.dumps(record.get('bounds',{}),ensure_ascii=False)
    return ob
records={r['source']:r for r in src if r.get('source') in ('keyboardKbkCase.3mf','keyboardRotator.3mf','keyboardJoystickCap.3mf')}
case=build_mesh(records['keyboardKbkCase.3mf'],'SRC_Case_keyboardKbkCase',lambda p:(p[0]-47.5,47.5-p[2],p[1]),case_mat,False)
rot=build_mesh(records['keyboardRotator.3mf'],'SRC_Knob_keyboardRotator',lambda p:(p[0],-p[2],p[1]),control_mat,True); rot.location.x=-67
joy=build_mesh(records['keyboardJoystickCap.3mf'],'SRC_JoystickCap_keyboardJoystickCap',lambda p:(p[0],-p[2],p[1]),control_mat,True); joy.location.x=67
scene['source_reference_layout']='CAD meshes converted to Blender mm, Z-up; detached controls are display offsets, not assembly coordinates.'
scene.unit_settings.system='METRIC'; scene.unit_settings.length_unit='MILLIMETERS'; scene.unit_settings.scale_length=1.0
scene.render.engine='BLENDER_EEVEE_NEXT'; scene.render.resolution_x=1600; scene.render.resolution_y=1200; scene.render.resolution_percentage=100; scene.render.image_settings.file_format='PNG'; scene.render.film_transparent=False
main=os.path.join(root,'assets','keyboard.blend'); bpy.ops.wm.save_as_mainfile(filepath=main); bpy.ops.wm.save_as_mainfile(filepath=os.path.join(root,'checkpoints','batch_01_source_geometry.blend'))
result={'saved':main,'objects':[(o.name,len(o.data.vertices),len(o.data.polygons),tuple(round(v,3) for v in o.dimensions)) for o in (case,rot,joy)],'sources':{k:len(v['vertex_data']) for k,v in records.items()}}

