import bpy, os
from mathutils import Vector
root=r'C:\Users\myw\Documents\ChatGPT\硬件\modeling'; scene=bpy.context.scene
scene.unit_settings.system='METRIC'; scene.unit_settings.scale_length=.001; scene.unit_settings.length_unit='MILLIMETERS'
coll=bpy.data.collections.get('90_Studio_Reference')
if coll is None: coll=bpy.data.collections.new('90_Studio_Reference'); scene.collection.children.link(coll)
for o in list(coll.objects): bpy.data.objects.remove(o,do_unlink=True)
for c in list(bpy.data.cameras):
    if c.users==0: bpy.data.cameras.remove(c)
for l in list(bpy.data.lights):
    if l.users==0: bpy.data.lights.remove(l)
world=scene.world; world.use_nodes=True
world.node_tree.nodes['Background'].inputs['Color'].default_value=(.035,.045,.06,1); world.node_tree.nodes['Background'].inputs['Strength'].default_value=.45
ld=bpy.data.lights.new('REF_Softbox','AREA'); lo=bpy.data.objects.new('REF_Softbox',ld); coll.objects.link(lo); lo.location=(0,-125,170); ld.energy=2200; ld.shape='DISK'; ld.size=130; lo.rotation_euler=(Vector((0,0,0))-lo.location).to_track_quat('-Z','Y').to_euler()
ld2=bpy.data.lights.new('REF_Fill','AREA'); lo2=bpy.data.objects.new('REF_Fill',ld2); coll.objects.link(lo2); lo2.location=(110,110,100); ld2.energy=1200; ld2.shape='DISK'; ld2.size=100; lo2.rotation_euler=(Vector((0,0,0))-lo2.location).to_track_quat('-Z','Y').to_euler()
views={'Top':((0,0,260),'Y'),'Front':((0,-260,0),'Z'),'Right':((260,0,0),'Z'),'Rear':((0,260,0),'Z'),'Bottom':((0,0,-260),'Y')}
cam_objects={}
for name,(pos,up) in views.items():
    data=bpy.data.cameras.new('REF_'+name+'_Camera'); data.type='ORTHO'; data.ortho_scale=188
    ob=bpy.data.objects.new('REF_'+name+'_Camera',data); coll.objects.link(ob); ob.location=pos; ob.rotation_euler=(Vector((0,0,0))-ob.location).to_track_quat('-Z',up).to_euler(); cam_objects[name]=ob
scene.camera=cam_objects['Top']; scene.render.engine='BLENDER_EEVEE'; scene.render.resolution_x=1500; scene.render.resolution_y=1250; scene.render.resolution_percentage=100
scene.view_settings.view_transform='Standard'; scene.view_settings.look='Medium High Contrast'; scene.view_settings.exposure=0; scene.view_settings.gamma=1
scene.render.image_settings.file_format='PNG'; scene.render.film_transparent=False
main=os.path.join(root,'assets','keyboard.blend'); bpy.ops.wm.save_as_mainfile(filepath=main); bpy.ops.wm.save_as_mainfile(filepath=os.path.join(root,'checkpoints','batch_01_source_geometry.blend'))
result={'units':{'system':scene.unit_settings.system,'scale_length':scene.unit_settings.scale_length,'length_unit':scene.unit_settings.length_unit},'cameras':list(cam_objects),'saved':main}

