def info(n):
 o=bpy.data.objects[n]; e=o.evaluated_get(dg)
 if e.type!="MESH": return {"name":n,"loc":list(e.matrix_world.translation)}
 pts=[e.matrix_world@v.co for v in e.data.vertices]
 return {"name":n,"parent":o.parent.name if o.parent else None,"bounds":[[min(p[i] for p in pts) for i in range(3)],[max(p[i] for p in pts) for i in range(3)]],"dims":list(e.dimensions),"mat":o.data.materials[0].name if o.data.materials else None}
